//! Committed fixtures generated by compiling and running the exact fork.
use thermopack_rs::{Cubic, CubicKind, Phase};

#[test]
fn matches_exact_source_fixtures() {
    let fixture = include_str!("fixtures/cubic.csv");
    let mut cases = 0;
    for line in fixture.lines().skip(1) {
        let columns: Vec<_> = line.split(';').collect();
        let fields: Vec<_> = columns[0].split('|').collect();
        let kind = match fields[0] {
            "PR" => CubicKind::PengRobinson,
            "SRK" => CubicKind::SoaveRedlichKwong,
            "RK" => CubicKind::RedlichKwong,
            "VDW" => CubicKind::VanDerWaals,
            _ => panic!("unexpected model"),
        };
        let model = Cubic::new(kind, &fields[1].split(',').collect::<Vec<_>>()).unwrap();
        let t: f64 = fields[2].parse().unwrap();
        let p: f64 = fields[3].parse().unwrap();
        let x: Vec<f64> = fields[4].split(',').map(|s| s.parse().unwrap()).collect();
        let phase = if fields[5] == "L" {
            Phase::Liquid
        } else {
            Phase::Vapor
        };
        let state = model.prepare(t, &x).unwrap();
        let v = state.volume(p, phase).unwrap();
        let pressure = state.pressure(v).unwrap();
        let residual = state.residual(v).unwrap();
        let mut actual = vec![
            v,
            pressure.value,
            pressure.dt,
            pressure.dv,
            residual.enthalpy,
            residual.entropy,
            state.enthalpy(v).unwrap(),
            state.entropy(v).unwrap(),
            state.baseline_enthalpy_derivative_tp(v).unwrap(),
        ];
        let mut phi = vec![0.0; x.len()];
        state.ln_fugacity_into(v, &mut phi).unwrap();
        actual.extend(phi);
        assert_eq!(actual.len(), columns.len() - 1);
        let absolute = [1e-14, 1e-2, 1e-6, 1e-2, 1e-7, 1e-9, 1e-7, 1e-9, 1e-7];
        for (i, (value, expected)) in actual.iter().zip(&columns[1..]).enumerate() {
            let expected: f64 = expected.parse().unwrap();
            let abs = absolute.get(i).copied().unwrap_or(1e-9);
            let relative = if i == 0 { 2e-9 } else { 2e-8 };
            let tolerance = abs + relative * expected.abs().max(value.abs());
            assert!(
                (value - expected).abs() <= tolerance,
                "{} quantity {i}: Rust {value}, reference {expected}, tolerance {tolerance}",
                columns[0]
            );
        }
        cases += 1;
    }
    assert_eq!(cases, 1320);
}

#[test]
fn pure_saturation_matches_exact_source() {
    let mut cases = 0;
    for line in include_str!("fixtures/saturation.csv").lines().skip(1) {
        let columns: Vec<_> = line.split(';').collect();
        let fields: Vec<_> = columns[0].split('|').collect();
        let kind = match fields[0] {
            "PR" => CubicKind::PengRobinson,
            "SRK" => CubicKind::SoaveRedlichKwong,
            "RK" => CubicKind::RedlichKwong,
            "VDW" => CubicKind::VanDerWaals,
            _ => panic!("unexpected model"),
        };
        let model = Cubic::new(kind, &[fields[1]]).unwrap();
        let sat = model
            .saturation_pressure(fields[2].parse().unwrap())
            .unwrap();
        let actual = [sat.pressure, sat.liquid_volume, sat.vapor_volume, sat.dpdt];
        let absolute = [1e-3, 1e-13, 1e-13, 1e-3];
        for (i, (value, expected)) in actual.iter().zip(&columns[1..]).enumerate() {
            let expected: f64 = expected.parse().unwrap();
            assert!(
                (value - expected).abs() <= absolute[i] + 2e-7 * expected.abs().max(value.abs()),
                "{} quantity {i}: Rust {value}, reference {expected}",
                columns[0]
            );
        }
        cases += 1;
    }
    assert_eq!(cases, 48);
}
